"""Independent low-dimensional product residual banks, same raw CAL/adapters."""
import argparse,json,pathlib,sys,time
import numpy as np
ROOT=pathlib.Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'src'))
from r14kv.common import json_save,sha
def main():
    import torch
    from r14kv.fitting import hadamard,nearest
    p=argparse.ArgumentParser();p.add_argument('--dim',type=int,choices=[8,16],required=True);p.add_argument('--run-id',required=True);a=p.parse_args();torch.set_num_threads(4);torch.backends.cuda.matmul.allow_tf32=False;torch.cuda.set_per_process_memory_fraction(22*2**30/torch.cuda.get_device_properties(0).total_memory);start=time.time();d=a.dim;g=128//d;stages=3*d//8
    out=ROOT/'data/runs'/a.run_id;out.mkdir(parents=True,exist_ok=True);dest=ROOT/'artifacts/ar17/packages'/f'PSRVQ_d{d}';dest.mkdir(parents=True,exist_ok=False);cal=ROOT/'artifacts/round14/calibration/round14_CAL64_capture_v1';cm=json.loads((cal/'completion.json').read_text());cap=cm['capacity'];slots=json.loads((ROOT/'data/runs/E02_train_G1_v1/slots.json').read_text());tr=slots['training'];va=slots['validation'];parent=ROOT/'artifacts/ar17/packages/CRVQ_extend32';pm=json.loads((parent/'completion.json').read_text());assert sha(parent/'global.pt')==pm['records'][0]['SHA256'];old=torch.load(parent/'global.pt',map_location='cpu',weights_only=True);table={k:old[k].clone() for k in ['K_mean','K_scale','V_mean','V_scale']};h=hadamard(128).float().cuda();table['H']=h.cpu().clone();orth=float((h.T@h-torch.eye(128,device='cuda')).square().mean());assert orth<=1e-8
    manifest={'run_id':a.run_id,'source_SHA256':sha(__file__),'CAL_completion_SHA256':sha(cal/'completion.json'),'direct_parent_SHA256':sha(parent/'completion.json'),'slot_manifest_SHA256':sha(ROOT/'data/runs/E02_train_G1_v1/slots.json'),'no_parent_centroids':True,'adapters_inherited_exact':True,'started_epoch':start,'group_dim':d,'stages':stages,'iterations':20,'training_scope':'historical CAL log-gradient weights, no DEV answers','independent_confirmation':False};json_save(out/'run_manifest.json',manifest);raw={k:{'train':[],'val':[],'weights':[]} for k in ['K','V']}
    for l in range(36):
        f=cal/f'layer{l:02}_vectors.u16';b=cal/f'layer{l:02}_gradient_norms.f32';assert sha(f)==cm['artifacts'][f.name]['SHA256'] and sha(b)==cm['artifacts'][b.name]['SHA256'];pool=np.memmap(f,mode='r',dtype=np.uint16,shape=(3,2,cap,128));grad=np.memmap(b,mode='r',dtype=np.float32,shape=(2,2,cap))
        for kind,ki,wi in [('K',0,0),('V',2,1)]:
            raw[kind]['train'].append(torch.from_numpy(np.array(pool[ki][:,tr])).view(torch.bfloat16).cuda().float());raw[kind]['val'].append(torch.from_numpy(np.array(pool[ki][:,va])).view(torch.bfloat16).cuda().float());w=torch.from_numpy(np.array(grad[wi][:,tr])).cuda().float();w=torch.log1p(w/(w.median(-1,keepdim=True).values+1e-12)).clamp_min(1e-8);raw[kind]['weights'].append(w)
    traces={}
    for side,kind in enumerate(['K','V']):
        tx=torch.stack(raw[kind]['train']);vx=torch.stack(raw[kind]['val']);mean=table[kind+'_mean'].cuda().float()[:,:,None];scale=table[kind+'_scale'].cuda().float()[:,:,None]
        def norm(x):
            u=(x-mean)/scale;rho=u.square().mean(-1,keepdim=True).sqrt().clamp_min(1e-6).bfloat16();return torch.matmul(u/rho.float(),h),rho
        z,rho=norm(tx);v,vrho=norm(vx);unit=((vx-mean)/scale)/vrho.float();roundtrip=float((torch.matmul(v,h.T)-unit).square().sum()/unit.square().sum());assert roundtrip<=1e-8;allx=z.reshape(1,-1,d);weights=torch.stack(raw[kind]['weights'])[...,None].expand(-1,-1,-1,g).reshape(1,-1);rng=np.random.default_rng(17261023+d+side*1000);selected=rng.choice(allx.shape[1],262144,replace=False).astype(np.int32);indexfile=out/('selected_blocks_'+kind+'.i32');selected.tofile(indexfile);ix=torch.from_numpy(selected.astype(np.int64)).cuda();x=allx[:,ix].clone();w=weights[:,ix].clone();vflat=v.reshape(1,-1,d);res=vflat.clone();decoded=torch.zeros_like(res);books=[];history=[]
        for r in range(stages):
            gen=torch.Generator(device='cuda').manual_seed(17261023+100*d+1000*side+r);pick=torch.randperm(x.shape[1],generator=gen,device='cuda')[:256];c=x[:,pick].clone()
            for _ in range(20):
                assignment=nearest(x,c);sums=torch.zeros_like(c);count=torch.zeros(1,256,device='cuda');sums.scatter_add_(1,assignment[...,None].expand(-1,-1,d),x*w[...,None]);count.scatter_add_(1,assignment,w);c=torch.where((count>0)[...,None],sums/count.clamp_min(1e-20)[...,None],c)
            deployed=c.half();assert torch.isfinite(deployed).all();cb=deployed.float();assign=nearest(x,cb);x-=torch.gather(cb,1,assign[...,None].expand(-1,-1,d));iv=nearest(res,cb);chosen=torch.gather(cb,1,iv[...,None].expand(-1,-1,d));res-=chosen;decoded+=chosen;books.append(deployed[0].cpu());vhat=torch.matmul(decoded.reshape_as(v),h.T);vhat=(vhat*vrho.float()*scale+mean).bfloat16().float();mse=float((vx-vhat).square().sum()/vx.square().sum());row={'stage':r+1,'bits_per_component':8*(r+1)/d,'validation_raw_relative_error':mse,'training_weighted_subvector_MSE':float((x.square().sum(-1)*w).sum()/w.sum()),'occupied':int(assign.unique().numel()),'seconds':time.time()-start};history.append(row);print(json.dumps({'side':kind,**row}),flush=True)
        table[kind+'_books']=torch.stack(books).contiguous();traces[kind]={'H_roundtrip_relative_error':roundtrip,'selected_blocks_SHA256':sha(indexfile),'available_training_blocks':allx.shape[1],'selected':262144,'history':history};json_save(out/'training_trace.json',traces)
    f=dest/'global.pt';torch.save(table,f);record={'layer':0,'file':f.name,'SHA256':sha(f),'tensors':{k:{'shape':list(x.shape),'dtype':str(x.dtype),'storage_bytes':x.untyped_storage().nbytes()} for k,x in table.items()}}
    done={**manifest,'completed':True,'CPU_export':True,'family':'PSRVQ','group_dim':d,'Rmax_K':stages,'Rmax_V':stages,'records':[record],'static_tensor_bytes':sum(x.untyped_storage().nbytes() for x in table.values()),'finished_epoch':time.time(),'elapsed_s':time.time()-start,'H_orthogonality_MSE':orth,'new_algorithm_claim':False};json_save(dest/'completion.json',done);json_save(out/'completion.json',done);print(json.dumps({'completed':True,'codec_MiB':done['static_tensor_bytes']/2**20,'seconds':time.time()-start}),flush=True)
if __name__=='__main__':main()
